package store

import (
	"bytes"
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"reflect"
	"syscall"
	"time"

	"codex-cli-orchestration-design/tools/orchestrator/internal/adapter"
)

// ReworkRefsRequest is a small authenticated control message. Text travels once
// through bounded chunks; paths and object identities are generated by Store.
type ReworkRefsRequest struct {
	Phase      string `json:"phase"`
	BodySize   int64  `json:"body_size,omitempty"`
	BodySHA256 string `json:"body_sha256,omitempty"`
	UploadID   string `json:"upload_id,omitempty"`
	Offset     int64  `json:"offset,omitempty"`
	Data       []byte `json:"data,omitempty"`
}
type ReworkUploadReceipt struct {
	Status        string         `json:"status"`
	CleanupReason string         `json:"cleanup_reason,omitempty"`
	UploadID      string         `json:"upload_id,omitempty"`
	WrittenBytes  int64          `json:"written_bytes,omitempty"`
	Receipt       *ReworkReceipt `json:"receipt,omitempty"`
}
type reworkRefsDecision struct {
	Kind       string                `json:"kind"`
	Owner      string                `json:"owner"`
	Spec       OwnerReworkSpec       `json:"request"`
	BodySHA256 string                `json:"body_sha256"`
	Receipt    ReworkReceipt         `json:"receipt"`
	Context    adapter.ReworkContext `json:"context"`
	Adapter    json.RawMessage       `json:"adapter"`
}

const reworkRefsDecisionKind = "owner_rework_refs_v3"

func (d *DB) reworkCut(phase string) error {
	if d.reworkFault != nil {
		return d.reworkFault(phase)
	}
	return nil
}

type reworkUpload struct{ id, owner, task, command, source, object, brief, status string }

func (d *DB) objectRoot() string { return filepath.Join(filepath.Dir(d.path), "rework-objects") }
func (d *DB) openObjectRoot() (*os.Root, error) {
	path := d.objectRoot()
	if e := os.Mkdir(path, 0700); e == nil {
		parent, x := os.Open(filepath.Dir(path))
		if x != nil {
			return nil, x
		}
		x = parent.Sync()
		parent.Close()
		if x != nil {
			return nil, x
		}
	} else if !os.IsExist(e) {
		return nil, e
	}
	info, e := os.Lstat(path)
	if e != nil || !info.IsDir() || info.Mode().Perm() != 0700 || !storeOwned(info) {
		return nil, CodeError("rework_object_invalid")
	}
	return os.OpenRoot(path)
}
func syncObjectRoot(root *os.Root) error {
	f, e := root.Open(".")
	if e != nil {
		return e
	}
	defer f.Close()
	return f.Sync()
}
func checkRefsHost(ctx context.Context, tx *sql.Tx, launch string) error {
	var ready, capable int
	if e := tx.QueryRowContext(ctx, `SELECT COUNT(*),COALESCE(SUM(owner_rework_refs_v3),0) FROM runtime_hosts WHERE launch_id=? AND status='ready'`, launch).Scan(&ready, &capable); e != nil {
		return e
	}
	if ready != 1 {
		return CodeError("rework_host_not_ready")
	}
	if capable != 1 {
		return CodeError("host_upgrade_required")
	}
	return nil
}
func (d *DB) loadObject(ctx context.Context, tx *sql.Tx, id string) (adapter.ReworkObjectRef, string, error) {
	var r adapter.ReworkObjectRef
	var status string
	e := tx.QueryRowContext(ctx, `SELECT id,owner,run_id,task_id,work_revision,kind,size,sha256,device,inode,status FROM rework_objects WHERE id=?`, id).Scan(&r.ID, &r.Owner, &r.RunID, &r.TaskID, &r.WorkRevision, &r.Kind, &r.Size, &r.SHA256, &r.Device, &r.Inode, &status)
	r.Path = filepath.Join(d.objectRoot(), r.ID+".json")
	return r, status, e
}
func loadUpload(ctx context.Context, tx *sql.Tx, id string) (reworkUpload, error) {
	var u reworkUpload
	e := tx.QueryRowContext(ctx, `SELECT id,owner,task_id,command_id,source_json,object_id,brief_id,status FROM rework_uploads WHERE id=?`, id).Scan(&u.id, &u.owner, &u.task, &u.command, &u.source, &u.object, &u.brief, &u.status)
	return u, e
}
func sameUpload(u reworkUpload, owner string, spec OwnerReworkSpec) bool {
	raw, _ := json.Marshal(spec)
	return u.owner == owner && u.task == spec.TaskID && u.command == spec.CommandID && u.source == string(raw)
}

// ReworkRefs authenticates owner again inside the write lock. No file descriptor
// survives this call. Reserved/published uploads stay charged and recoverable
// until an explicit exact abort; elapsed wall time never authorizes deletion.
func (d *DB) ReworkRefs(ctx context.Context, owner string, spec OwnerReworkSpec, req ReworkRefsRequest) (ReworkUploadReceipt, error) {
	empty := ReworkUploadReceipt{}
	sourceBytes, _ := json.Marshal(spec)
	if len(sourceBytes) > 4096 {
		return empty, CodeError("invalid_request_changes")
	}
	probe := spec
	probe.Feedback = "reference"
	probe.Acceptance = "reference"
	if validateOwnerRework(probe) != nil || spec.Feedback != "" || spec.Acceptance != "" || owner == "" || len(req.Data) > adapter.ReworkChunkMaxBytes {
		return empty, CodeError("invalid_request_changes")
	}
	d.mu.Lock()
	defer d.mu.Unlock()
	tx, e := d.sql.BeginTx(ctx, nil)
	if e != nil {
		return empty, e
	}
	defer tx.Rollback()
	if e = validateOwnerActionBinding(ctx, tx, spec.TaskID); e != nil {
		return empty, e
	}
	var actualOwner string
	if e = tx.QueryRowContext(ctx, `SELECT r.controller_thread FROM runs r JOIN tasks t ON t.run_id=r.id WHERE t.id=?`, spec.TaskID).Scan(&actualOwner); e != nil || actualOwner != owner {
		return empty, ErrConflict
	}
	// Replay precedes dynamic availability and current revision eligibility.
	var previous string
	e = tx.QueryRowContext(ctx, `SELECT revision_payload FROM retry_decisions WHERE command_id=? OR action_slot=? OR source_event_id=?`, spec.CommandID, spec.ActionSlot, spec.EventID).Scan(&previous)
	if e == nil {
		var saved reworkRefsDecision
		if json.Unmarshal([]byte(previous), &saved) != nil || saved.Kind != reworkRefsDecisionKind || saved.Owner != owner || !reflect.DeepEqual(saved.Spec, spec) || (req.BodySHA256 != "" && req.BodySHA256 != saved.BodySHA256) {
			return empty, ErrConflict
		}
		return ReworkUploadReceipt{Status: saved.Receipt.Status, Receipt: &saved.Receipt}, nil
	}
	if !errors.Is(e, sql.ErrNoRows) {
		return empty, e
	}
	if req.Phase == "begin" {
		return d.beginReworkRefs(ctx, tx, owner, spec, req)
	}
	u, e := loadUpload(ctx, tx, req.UploadID)
	if e != nil || !sameUpload(u, owner, spec) {
		return empty, ErrConflict
	}
	if req.Phase == "abort" {
		if u.status == "committed" {
			return empty, ErrConflict
		}
		if _, e = tx.ExecContext(ctx, `UPDATE rework_uploads SET status='abandoned' WHERE id=?`, u.id); e != nil {
			return empty, e
		}
		if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET status='abandoned' WHERE id IN (?,?) AND status IN ('reserved','published') AND NOT EXISTS(SELECT 1 FROM rework_pins WHERE object_id=rework_objects.id) AND NOT EXISTS(SELECT 1 FROM rework_uploads WHERE status='active' AND (object_id=rework_objects.id OR brief_id=rework_objects.id))`, u.object, u.brief); e != nil {
			return empty, e
		}
		if e = tx.Commit(); e != nil {
			return empty, e
		}
		return ReworkUploadReceipt{Status: "abandoned", UploadID: u.id}, nil
	}
	if req.Phase == "gc" {
		if u.status != "abandoned" {
			return empty, ErrConflict
		}
		return d.gcReworkRefs(ctx, tx, u)
	}
	if u.status != "active" {
		return empty, ErrConflict
	}
	ref, status, e := d.loadObject(ctx, tx, u.object)
	if e != nil {
		return empty, e
	}
	if req.Phase == "chunk" {
		if req.Offset < 0 || len(req.Data) == 0 || req.Offset > ref.Size-int64(len(req.Data)) || status != "reserved" {
			return empty, CodeError("rework_chunk_invalid")
		}
		if e = tx.Rollback(); e != nil {
			return empty, e
		}
		n, e := d.writeObjectChunk(ctx, ref, req.Offset, req.Data)
		return ReworkUploadReceipt{Status: "uploading", UploadID: u.id, WrittenBytes: n}, e
	}
	if req.Phase != "commit" {
		return empty, CodeError("invalid_request_changes")
	}
	if e = tx.Rollback(); e != nil {
		return empty, e
	}
	if e = d.ensureUploadBrief(ctx, u); e != nil {
		return empty, e
	}
	if _, e = d.publishObject(ctx, ref); e != nil {
		return empty, e
	}
	return d.commitReworkRefs(ctx, owner, spec, u)
}

func (d *DB) beginReworkRefs(ctx context.Context, tx *sql.Tx, owner string, spec OwnerReworkSpec, req ReworkRefsRequest) (ReworkUploadReceipt, error) {
	empty := ReworkUploadReceipt{}
	if req.BodySize < 1 || req.BodySize > adapter.ReworkBodyMaxBytes || !validDigest(req.BodySHA256) {
		return empty, CodeError("rework_body_too_large")
	}
	var existing string
	e := tx.QueryRowContext(ctx, `SELECT id FROM rework_uploads WHERE command_id=?`, spec.CommandID).Scan(&existing)
	if e == nil {
		u, e := loadUpload(ctx, tx, existing)
		if e != nil || !sameUpload(u, owner, spec) || u.status != "active" {
			return empty, ErrConflict
		}
		r, _, e := d.loadObject(ctx, tx, u.object)
		if e != nil || r.Size != req.BodySize || r.SHA256 != req.BodySHA256 {
			return empty, ErrConflict
		}
		var n int64
		if e = tx.QueryRowContext(ctx, `SELECT written_bytes FROM rework_objects WHERE id=?`, r.ID).Scan(&n); e != nil {
			return empty, e
		}
		return ReworkUploadReceipt{Status: "uploading", UploadID: u.id, WrittenBytes: n}, nil
	}
	if !errors.Is(e, sql.ErrNoRows) {
		return empty, e
	}
	v, e := d.ownerReworkEligibility(ctx, tx, spec.TaskID)
	if e != nil {
		return empty, e
	}
	if e = matchReworkSource(v, spec); e != nil {
		return empty, e
	}
	if e = checkRefsHost(ctx, tx, v.task.hostLaunch); e != nil {
		return empty, e
	}
	p := v.payload
	if (p.CandidateWorkspace.Rework == nil && spec.WorkRevision != 1) || (p.CandidateWorkspace.Rework != nil && p.CandidateWorkspace.Rework.Version != 3) {
		return empty, CodeError("rework_legacy_upgrade_unsupported")
	}
	var briefID string
	var briefBytes []byte
	if p.CandidateWorkspace.Rework == nil {
		body := adapter.ReworkBody{Version: 3, Kind: "brief", Owner: owner, RunID: v.run, TaskID: spec.TaskID, WorkRevision: 1, Prompt: p.Prompt}
		briefBytes, _ = json.Marshal(body)
		if _, e = adapter.DecodeReworkBody(briefBytes); e != nil {
			return empty, e
		}
		briefID = runtimeHash("brief\x00" + owner + "\x00" + v.run + "\x00" + spec.TaskID)
	} else {
		refs := p.CandidateWorkspace.Rework.RefsV3
		if refs == nil || refs.Owner != owner || len(refs.Conditions) >= 2 {
			return empty, ErrConflict
		}
		briefID = refs.Brief.ID
	}
	newBrief := len(briefBytes) > 0
	if newBrief {
		existing, status, x := d.loadObject(ctx, tx, briefID)
		if x == nil {
			if existing.Owner != owner || existing.RunID != v.run || existing.TaskID != spec.TaskID || existing.WorkRevision != 1 || existing.Kind != "brief" || existing.Size != int64(len(briefBytes)) || existing.SHA256 != runtimeHash(string(briefBytes)) {
				return empty, ErrConflict
			}
			if status == "deleting" {
				return empty, CodeError("rework_cleanup_pending")
			}
			newBrief = false
			if status == "abandoned" {
				if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET status='reserved' WHERE id=?`, briefID); e != nil {
					return empty, e
				}
			}
		} else if !errors.Is(x, sql.ErrNoRows) {
			return empty, x
		}
	}
	incoming := req.BodySize + 4096 + 4096 // object overhead and upload metadata
	if newBrief {
		incoming += int64(len(briefBytes)) + 4096
	}
	if e = d.storageAdmission(ctx, tx, v.run, incoming+ownerReworkMaxDecisionBytes, false); e != nil {
		return empty, e
	}
	uploadID := runtimeHash("upload\x00" + owner + "\x00" + v.run + "\x00" + spec.TaskID + "\x00" + spec.CommandID)
	objectID := runtimeHash("condition\x00" + uploadID)
	add := func(id, kind string, size int64, hash string, revision int) error {
		_, e := tx.ExecContext(ctx, `INSERT INTO rework_objects(id,owner,run_id,task_id,work_revision,kind,size,sha256,status,charged_bytes) VALUES(?,?,?,?,?,?,?,?,'reserved',?)`, id, owner, v.run, spec.TaskID, revision, kind, size, hash, size+4096)
		return e
	}
	if newBrief {
		if e = add(briefID, "brief", int64(len(briefBytes)), runtimeHash(string(briefBytes)), 1); e != nil {
			return empty, e
		}
	}
	if e = add(objectID, "condition", req.BodySize, req.BodySHA256, spec.WorkRevision); e != nil {
		return empty, e
	}
	source, _ := json.Marshal(spec)
	if _, e = tx.ExecContext(ctx, `INSERT INTO rework_uploads VALUES(?,?,?,?,?,?,?,'active')`, uploadID, owner, spec.TaskID, spec.CommandID, string(source), objectID, briefID); e != nil {
		return empty, e
	}
	if e = tx.Commit(); e != nil {
		return empty, e
	}
	if e = d.reworkCut("reserved"); e != nil {
		return empty, e
	}
	// Reservation is durable before opening the first file. A crash here leaves
	// a charged recoverable intent, never an unaccounted staging file.
	if e = d.ensureUploadBrief(ctx, reworkUpload{id: uploadID, owner: owner, task: spec.TaskID, command: spec.CommandID, object: objectID, brief: briefID, status: "active"}); e != nil {
		return empty, e
	}
	return ReworkUploadReceipt{Status: "uploading", UploadID: uploadID}, nil
}

func matchReworkSource(v ownerReworkState, s OwnerReworkSpec) error {
	e := v.event
	if s.WorkRevision != v.task.revision || s.EventID != e.EventID || s.EventRevision != e.EventRevision || s.EventHash != e.PayloadHash || s.ActionSlot != e.ActionSlot || s.SegmentID != e.SegmentID || s.CandidateOID != v.candidate.CandidateOID {
		return ErrConflict
	}
	return nil
}

func (d *DB) writeObjectChunk(ctx context.Context, ref adapter.ReworkObjectRef, offset int64, data []byte) (int64, error) {
	tx, e := d.sql.BeginTx(ctx, nil)
	if e != nil {
		return 0, e
	}
	defer tx.Rollback()
	var taskID string
	if e = tx.QueryRowContext(ctx, `SELECT task_id FROM rework_objects WHERE id=?`, ref.ID).Scan(&taskID); e != nil {
		return 0, e
	}
	if e = validateOwnerActionBinding(ctx, tx, taskID); e != nil {
		return 0, e
	}
	root, e := d.openObjectRoot()
	if e != nil {
		return 0, e
	}
	defer root.Close()
	name := ref.ID + ".stage"
	f, e := root.OpenFile(name, os.O_RDWR|os.O_CREATE|os.O_EXCL|syscall.O_NOFOLLOW, 0600)
	created := e == nil
	if os.IsExist(e) {
		f, e = root.OpenFile(name, os.O_RDWR|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	}
	if e != nil {
		return 0, e
	}
	defer f.Close()
	info, e := f.Stat()
	if e != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0600 || !storeOwned(info) {
		return 0, CodeError("rework_object_invalid")
	}
	st, ok := info.Sys().(*syscall.Stat_t)
	if !ok || st.Nlink != 1 {
		return 0, CodeError("rework_object_invalid")
	}
	var status string
	var written, device, inode int64
	if e = tx.QueryRowContext(ctx, `SELECT status,written_bytes,device,inode FROM rework_objects WHERE id=?`, ref.ID).Scan(&status, &written, &device, &inode); e != nil {
		return 0, e
	}
	if status != "reserved" || offset > written || info.Size() < written || info.Size() > ref.Size || (inode != 0 && (uint64(device) != uint64(st.Dev) || uint64(inode) != st.Ino)) {
		return 0, CodeError("rework_object_invalid")
	}
	if inode == 0 && !created {
		return 0, CodeError("rework_cleanup_identity_unknown")
	}
	if inode == 0 {
		if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET device=?,inode=? WHERE id=? AND inode=0`, uint64(st.Dev), st.Ino, ref.ID); e != nil {
			return 0, e
		}
	}
	// A crash can leave a prefix of this chunk beyond written_bytes. Compare that
	// prefix before completing it; a different replay can never overwrite it.
	existing := info.Size() - offset
	if existing > int64(len(data)) {
		existing = int64(len(data))
	}
	if existing > 0 {
		old := make([]byte, int(existing))
		if _, e = f.ReadAt(old, offset); e != nil || !bytes.Equal(old, data[:existing]) {
			return 0, ErrConflict
		}
	}
	end := offset + int64(len(data))
	if end > info.Size() {
		start := info.Size() - offset
		if start < 0 {
			return 0, ErrConflict
		}
		if _, e = f.WriteAt(data[start:], info.Size()); e != nil {
			return 0, e
		}
	}
	if e = f.Sync(); e != nil {
		return 0, e
	}
	if e = syncObjectRoot(root); e != nil {
		return 0, e
	}
	if end < written {
		end = written
	}
	if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET written_bytes=? WHERE id=? AND status='reserved'`, end, ref.ID); e != nil {
		return 0, e
	}
	if e = tx.Commit(); e != nil {
		return 0, e
	}
	return end, nil
}

func (d *DB) publishObject(ctx context.Context, ref adapter.ReworkObjectRef) (adapter.ReworkObjectRef, error) {
	root, e := d.openObjectRoot()
	if e != nil {
		return ref, e
	}
	defer root.Close()
	tx, e := d.sql.BeginTx(ctx, nil)
	if e != nil {
		return ref, e
	}
	defer tx.Rollback()
	saved, status, e := d.loadObject(ctx, tx, ref.ID)
	if e != nil {
		return ref, e
	}
	ref = saved
	if e = validateOwnerActionBinding(ctx, tx, ref.TaskID); e != nil {
		return ref, e
	}
	if status == "published" || status == "pinned" {
		_, e = adapter.ReadReworkObject(d.objectRoot(), ref)
		return ref, e
	}
	if status != "reserved" || ref.Inode == 0 {
		return ref, CodeError("rework_object_invalid")
	}
	stage, final := ref.ID+".stage", ref.ID+".json"
	info, e := root.Lstat(stage)
	onlyFinal := false
	if os.IsNotExist(e) {
		info, e = root.Lstat(final)
		onlyFinal = true
	}
	if e != nil {
		return ref, e
	}
	st, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || !storeOwned(info) || info.Mode().Perm() != 0600 || info.Size() != ref.Size || uint64(st.Dev) != ref.Device || (st.Ino != ref.Inode || st.Nlink < 1 || st.Nlink > 2 || (onlyFinal && st.Nlink != 1)) {
		return ref, CodeError("rework_object_invalid")
	}
	readName := stage
	if onlyFinal {
		readName = final
	}
	f, e := root.OpenFile(readName, os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if e != nil {
		return ref, e
	}
	opened, x := f.Stat()
	if x != nil || !os.SameFile(info, opened) {
		f.Close()
		return ref, CodeError("rework_object_invalid")
	}
	data, e := io.ReadAll(io.LimitReader(f, ref.Size+1))
	if e == nil {
		e = f.Sync()
	}
	f.Close()
	if e != nil || int64(len(data)) != ref.Size || runtimeHash(string(data)) != ref.SHA256 {
		return ref, CodeError("rework_object_invalid")
	}
	body, e := adapter.DecodeReworkBody(data)
	if e != nil || body.Owner != ref.Owner || body.RunID != ref.RunID || body.TaskID != ref.TaskID || body.WorkRevision != ref.WorkRevision || body.Kind != ref.Kind {
		return ref, CodeError("rework_object_invalid")
	}
	// Link is no-overwrite. Recovery accepts only the exact recorded inode.
	if !onlyFinal {
		if e = root.Link(stage, final); e != nil {
			fi, x := root.Lstat(final)
			if x != nil || !os.SameFile(info, fi) {
				return ref, CodeError("rework_object_invalid")
			}
		}
	}
	if e = syncObjectRoot(root); e != nil {
		return ref, e
	}
	if e = d.reworkCut("published_link"); e != nil {
		return ref, e
	}
	if !onlyFinal {
		if e = root.Remove(stage); e != nil {
			return ref, e
		}
	}
	if e = syncObjectRoot(root); e != nil {
		return ref, e
	}
	if e = d.reworkCut("published_unrecorded"); e != nil {
		return ref, e
	}
	if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET status='published' WHERE id=? AND status='reserved'`, ref.ID); e != nil {
		return ref, e
	}
	if e = tx.Commit(); e != nil {
		return ref, e
	}
	return ref, nil
}

func (d *DB) commitReworkRefs(ctx context.Context, owner string, spec OwnerReworkSpec, u reworkUpload) (ReworkUploadReceipt, error) {
	empty := ReworkUploadReceipt{}
	tx, e := d.sql.BeginTx(ctx, nil)
	if e != nil {
		return empty, e
	}
	defer tx.Rollback()
	if e = validateOwnerActionBinding(ctx, tx, spec.TaskID); e != nil {
		return empty, e
	}
	v, e := d.ownerReworkEligibility(ctx, tx, spec.TaskID)
	if e != nil {
		return empty, e
	}
	if e = matchReworkSource(v, spec); e != nil {
		return empty, e
	}
	if e = checkRefsHost(ctx, tx, v.task.hostLaunch); e != nil {
		return empty, e
	}
	brief, bs, e := d.loadObject(ctx, tx, u.brief)
	if e != nil {
		return empty, e
	}
	body, status, e := d.loadObject(ctx, tx, u.object)
	if e != nil || status != "published" || (bs != "published" && bs != "pinned") {
		return empty, CodeError("rework_object_invalid")
	}
	refs := adapter.ReworkRefs{Version: 3, Owner: owner, RunID: v.run, TaskID: spec.TaskID, WorkRevision: spec.WorkRevision + 1, Brief: brief}
	if old := v.payload.CandidateWorkspace.Rework; old != nil {
		if old.Version != 3 || old.RefsV3 == nil {
			return empty, CodeError("rework_legacy_upgrade_unsupported")
		}
		refs.Conditions = append(refs.Conditions, old.RefsV3.Conditions...)
	}
	refs.Conditions = append(refs.Conditions, body)
	manifest, _ := json.Marshal(refs)
	if len(manifest) > adapter.ReworkManifestMaxBytes || len(refs.Conditions) > 2 {
		return empty, CodeError("rework_payload_too_large")
	}
	// Verify every historical condition before pinning. These exact bytes are
	// authoritative; only small refs, never feedback text, enter the decision.
	bodies := []adapter.ReworkBody{}
	for i, r := range append([]adapter.ReworkObjectRef{refs.Brief}, refs.Conditions...) {
		data, x := adapter.ReadReworkObject(d.objectRoot(), r)
		if x != nil {
			return empty, x
		}
		b, x := adapter.DecodeReworkBody(data)
		if x != nil || b.Owner != owner || b.RunID != v.run || b.TaskID != spec.TaskID || b.WorkRevision != r.WorkRevision || b.Kind != r.Kind || r.Owner != owner || r.RunID != v.run || r.TaskID != spec.TaskID || (i == 0 && (r.Kind != "brief" || r.WorkRevision != 1)) || (i > 0 && (r.Kind != "condition" || r.WorkRevision != i)) {
			return empty, CodeError("rework_object_invalid")
		}
		bodies = append(bodies, b)
	}
	prompt, e := adapter.AssembleReworkBodies(bodies)
	if e != nil {
		return empty, e
	}
	transport, e := adapter.BuildInvocation(adapter.Request{Provider: adapter.Provider(v.payload.Provider), Binary: v.payload.ProviderLock.Binary, Lock: v.payload.ProviderLock, Profile: v.payload.Profile, CWD: v.payload.Directory, Prompt: prompt, Permission: adapter.Permission{Mode: v.payload.PermissionMode, Allow: v.payload.Allow, Deny: v.payload.Deny}, ExtraArgs: v.payload.ExtraArgs, Workspace: v.payload.CandidateWorkspace})
	if e != nil {
		return empty, e
	}
	if len(transport.Stdin()) > adapter.ReworkInputMaxBytes {
		return empty, CodeError("rework_input_too_large")
	}
	c := adapter.ReworkContext{Version: 3, RunID: v.run, TaskID: spec.TaskID, PreviousWorkRevision: spec.WorkRevision, PreviousCandidateOID: spec.CandidateOID, CandidateEventID: spec.EventID, CandidateSHA256: spec.EventHash, Source: "owner", OwnerDecisionID: spec.CommandID, RefsV3: &refs}
	p := v.payload
	p.CandidateWorkspace.BaseOID = spec.CandidateOID
	p.CandidateWorkspace.Rework = &c
	p.CandidateWorkspace.AutoDirectory = true
	p.Directory = fmt.Sprintf("%s.owner-revision-%d", p.Directory, spec.WorkRevision+1)
	p.Prompt = adapter.ReworkPromptMarker
	raw, e := json.Marshal(p)
	if e != nil {
		return empty, e
	}
	if len(raw) > 16*1024 {
		return empty, CodeError("rework_payload_too_large")
	}
	receipt := ReworkReceipt{Status: "rework_queued", TaskID: spec.TaskID, WorkRevision: spec.WorkRevision + 1, CandidateOID: spec.CandidateOID, RevisionSHA256: c.Digest(), TaskRevisions: map[string]int{spec.TaskID: spec.WorkRevision + 1}}
	saved := reworkRefsDecision{Kind: reworkRefsDecisionKind, Owner: owner, Spec: spec, BodySHA256: body.SHA256, Receipt: receipt, Context: c, Adapter: raw}
	encoded, e := json.Marshal(saved)
	if e != nil {
		return empty, e
	}
	if len(encoded) > ownerReworkMaxDecisionBytes {
		return empty, CodeError("rework_payload_too_large")
	}
	if e = d.storageAdmission(ctx, tx, v.run, int64(len(encoded)), false); e != nil {
		return empty, e
	}
	if _, e = tx.ExecContext(ctx, `INSERT INTO retry_decisions(action_slot,task_id,work_revision,source_event_id,source_event_revision,source_event_hash,source_segment_id,next_attempt_no,use_next_fallback,command_id,created_at,revision_payload) VALUES(?,?,?,?,?,?,?,?,0,?,?,?)`, spec.ActionSlot, spec.TaskID, spec.WorkRevision, spec.EventID, spec.EventRevision, spec.EventHash, spec.SegmentID, v.attempts+1, spec.CommandID, time.Now().UTC().Format(time.RFC3339Nano), string(encoded)); e != nil {
		return empty, mapConflict(e)
	}
	for _, r := range append([]adapter.ReworkObjectRef{refs.Brief}, refs.Conditions...) {
		if _, e = tx.ExecContext(ctx, `INSERT INTO rework_pins(object_id,command_id) VALUES(?,?)`, r.ID, spec.CommandID); e != nil {
			return empty, e
		}
		if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET status='pinned' WHERE id=? AND status IN ('published','pinned')`, r.ID); e != nil {
			return empty, e
		}
	}
	sequence, e := takeReadySequence(ctx, tx)
	if e != nil {
		return empty, e
	}
	if _, e = tx.ExecContext(ctx, `UPDATE tasks SET status='ready' WHERE id=?`, spec.TaskID); e != nil {
		return empty, e
	}
	if _, e = tx.ExecContext(ctx, `UPDATE task_runtime SET work_revision=work_revision+1,adapter_payload=?,ready_sequence=? WHERE task_id=?`, string(raw), sequence, spec.TaskID); e != nil {
		return empty, e
	}
	if _, e = tx.ExecContext(ctx, `UPDATE report_capabilities SET status='revoked' WHERE task_id=?`, spec.TaskID); e != nil {
		return empty, e
	}
	if _, e = tx.ExecContext(ctx, `UPDATE rework_uploads SET status='committed' WHERE id=? AND status='active'`, u.id); e != nil {
		return empty, e
	}
	if e = d.reworkCut("before_decision_commit"); e != nil {
		return empty, e
	}
	if e = tx.Commit(); e != nil {
		return empty, e
	}
	if e = d.reworkCut("after_decision_commit"); e != nil {
		return empty, e
	}
	return ReworkUploadReceipt{Status: receipt.Status, UploadID: u.id, Receipt: &receipt}, nil
}

func (d *DB) gcReworkRefs(ctx context.Context, tx *sql.Tx, u reworkUpload) (ReworkUploadReceipt, error) {
	empty := ReworkUploadReceipt{}
	refs := []adapter.ReworkObjectRef{}
	for _, id := range []string{u.object, u.brief} {
		r, status, e := d.loadObject(ctx, tx, id)
		if errors.Is(e, sql.ErrNoRows) {
			continue
		}
		if e != nil {
			return empty, e
		}
		if status != "abandoned" && status != "deleting" {
			continue
		}
		var live int
		if e = tx.QueryRowContext(ctx, `SELECT (SELECT COUNT(*) FROM rework_pins WHERE object_id=?)+(SELECT COUNT(*) FROM rework_uploads WHERE status='active' AND (object_id=? OR brief_id=?))`, id, id, id).Scan(&live); e != nil {
			return empty, e
		}
		if live != 0 {
			return empty, ErrConflict
		}
		refs = append(refs, r)
		if _, e = tx.ExecContext(ctx, `UPDATE rework_objects SET status='deleting' WHERE id=?`, id); e != nil {
			return empty, e
		}
	}
	if e := tx.Commit(); e != nil {
		return empty, e
	}
	root, e := d.openObjectRoot()
	if e != nil {
		return empty, e
	}
	defer root.Close()
	if len(refs) > 0 {
		pending, x := existingReworkQuarantine(root, u.id)
		if x != nil {
			return empty, x
		}
		if pending {
			return empty, quarantinePending
		}
	}
	var quarantine *reworkQuarantine
	for _, r := range refs {
		deleteTx, x := d.sql.BeginTx(ctx, nil)
		if x != nil {
			return empty, x
		}
		defer deleteTx.Rollback()
		if x = validateOwnerActionBinding(ctx, deleteTx, r.TaskID); x != nil {
			return empty, x
		}
		names, held, x := reworkCleanupLinks(root, r)
		if x != nil {
			return empty, x
		}
		if held != nil {
			defer held.Close()
		}
		if len(names) > 0 && quarantine == nil {
			if x = reworkCleanupPlatform(); x != nil {
				return empty, x
			}
			quarantine, x = newReworkQuarantine(root, u.id)
			if x != nil {
				return empty, x
			}
			defer quarantine.Close()
		}
		for index, name := range names {
			// Recheck each name against the recorded inode and remaining known links.
			info, x := root.Lstat(name)
			if x != nil {
				return empty, x
			}
			st, ok := info.Sys().(*syscall.Stat_t)
			if !ok || !info.Mode().IsRegular() || !storeOwned(info) || info.Mode().Perm() != 0600 || st.Ino != r.Inode || uint64(st.Dev) != r.Device || int(st.Nlink) != len(names)-index {
				return empty, CodeError("rework_cleanup_identity_unknown")
			}
			if x = d.reworkCut("gc_before_unlink"); x != nil {
				return empty, x
			}
			if x = quarantine.captureAndRemove(name, r, len(names)-index, d.reworkCut); x != nil {
				return empty, x
			}
		}

		if e = syncObjectRoot(root); e != nil {
			return empty, e
		}
		if held != nil {
			info, x := held.Stat()
			if x != nil {
				return empty, x
			}
			st, ok := info.Sys().(*syscall.Stat_t)
			if !ok || st.Nlink != 0 {
				return empty, CodeError("rework_cleanup_identity_unknown")
			}
		}
		// Keep the abandoned upload as an idempotence tombstone; it no longer
		// grants writer/recovery authority. FK references clear before row removal.
		if _, e = deleteTx.ExecContext(ctx, `DELETE FROM rework_objects WHERE id=? AND status='deleting'`, r.ID); e != nil {
			return empty, e
		}
		if e = deleteTx.Commit(); e != nil {
			return empty, e
		}
	}
	return ReworkUploadReceipt{Status: "removed", UploadID: u.id, CleanupReason: "upload_tombstone_and_quarantine_barrier_retained"}, nil
}

// A reservation-before-file crash can be recovered from the still unchanged
// rev1 payload. Its exact bytes must match the already durable expected digest.
func (d *DB) ensureUploadBrief(ctx context.Context, u reworkUpload) error {
	tx, e := d.sql.BeginTx(ctx, nil)
	if e != nil {
		return e
	}
	r, status, e := d.loadObject(ctx, tx, u.brief)
	if e != nil {
		tx.Rollback()
		return e
	}
	if status == "published" || status == "pinned" {
		tx.Rollback()
		_, e = adapter.ReadReworkObject(d.objectRoot(), r)
		return e
	}
	var raw string
	e = tx.QueryRowContext(ctx, `SELECT adapter_payload FROM task_runtime WHERE task_id=?`, u.task).Scan(&raw)
	tx.Rollback()
	if e != nil {
		return e
	}
	root, x := d.openObjectRoot()
	if x != nil {
		return x
	}
	stageInfo, sx := root.Lstat(r.ID + ".stage")
	_, fx := root.Lstat(r.ID + ".json")
	root.Close()
	if r.Inode != 0 && ((sx == nil && stageInfo.Size() == r.Size) || fx == nil) {
		_, e = d.publishObject(ctx, r)
		return e
	}
	p, e := adapter.DecodeInvocationPayload([]byte(raw))
	if e != nil || p.CandidateWorkspace == nil || p.CandidateWorkspace.Rework != nil {
		return CodeError("rework_object_invalid")
	}
	b := adapter.ReworkBody{Version: 3, Kind: "brief", Owner: r.Owner, RunID: r.RunID, TaskID: r.TaskID, WorkRevision: 1, Prompt: p.Prompt}
	data, _ := json.Marshal(b)
	if int64(len(data)) != r.Size || runtimeHash(string(data)) != r.SHA256 {
		return CodeError("rework_object_invalid")
	}
	if _, e = d.writeObjectChunk(ctx, r, 0, data); e != nil {
		return e
	}
	_, e = d.publishObject(ctx, r)
	return e
}

// Preflight the complete known link set before deleting any name. A held
// no-follow descriptor also proves nlink==0 after unlink/fsync, so a late extra
// hardlink cannot cause quota release. No descriptor survives the RPC.
func reworkCleanupLinks(root *os.Root, r adapter.ReworkObjectRef) ([]string, *os.File, error) {
	bad := CodeError("rework_cleanup_identity_unknown")
	names := []string{}
	infos := []os.FileInfo{}
	for _, suffix := range []string{".stage", ".json"} {
		name := r.ID + suffix
		info, e := root.Lstat(name)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return nil, nil, e
		}
		st, ok := info.Sys().(*syscall.Stat_t)
		if !ok || !info.Mode().IsRegular() || !storeOwned(info) || info.Mode().Perm() != 0600 || r.Inode == 0 || st.Ino != r.Inode || uint64(st.Dev) != r.Device {
			return nil, nil, bad
		}
		names = append(names, name)
		infos = append(infos, info)
	}
	if len(names) == 0 {
		if r.Inode != 0 {
			return nil, nil, bad
		}
		return names, nil, nil
	}
	for _, info := range infos {
		st := info.Sys().(*syscall.Stat_t)
		if int(st.Nlink) != len(names) {
			return nil, nil, bad
		}
	}
	held, e := root.OpenFile(names[0], os.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if e != nil {
		return nil, nil, e
	}
	opened, e := held.Stat()
	if e != nil || !os.SameFile(infos[0], opened) {
		held.Close()
		return nil, nil, bad
	}
	st, ok := opened.Sys().(*syscall.Stat_t)
	if !ok || int(st.Nlink) != len(names) {
		held.Close()
		return nil, nil, bad
	}
	return names, held, nil
}
